"""Metadata extraction against clips generated by ffmpeg with known values."""
import shutil
import struct
import subprocess
from datetime import date, datetime

import pytest

from media_ingest.metadata import (
    camera_model,
    ToolStatus,
    clip_datetimes,
    extract_card,
    find_tools,
    read_exif,
    select_clips,
)
from media_ingest.shootdate import propose_shoot_date
from media_ingest.sources import list_source

pytestmark = pytest.mark.skipif(
    not (shutil.which("ffmpeg") and shutil.which("ffprobe") and shutil.which("exiftool")),
    reason="needs ffmpeg, ffprobe and exiftool",
)

IXML = (b'<?xml version="1.0" encoding="UTF-8"?><BWFXML><IXML_VERSION>2.1</IXML_VERSION><SPEED>'
        b"<TIMECODE_RATE>{rate}</TIMECODE_RATE><TIMECODE_FLAG>{flag}</TIMECODE_FLAG>"
        b"<TIMESTAMP_SAMPLE_RATE>48000</TIMESTAMP_SAMPLE_RATE></SPEED></BWFXML>")


def ffmpeg(*args):
    subprocess.run(["ffmpeg", "-v", "error", "-y", *map(str, args)], check=True)


def video(path, size="320x240", rate="25", seconds=1, codec=("-c:v", "libx264"), extra=()):
    path.parent.mkdir(parents=True, exist_ok=True)
    ffmpeg("-f", "lavfi", "-i", f"testsrc=size={size}:rate={rate}", "-t", seconds, *codec, *extra, path)


def bwf(path, ixml=None):
    path.parent.mkdir(parents=True, exist_ok=True)
    ffmpeg("-f", "lavfi", "-i", "sine", "-t", 1, "-ar", 48000, "-ac", 2, "-c:a", "pcm_s24le", "-write_bext", 1,
           "-metadata", "time_reference=172800000", "-metadata", "origination_date=2026-10-12",
           "-metadata", "origination_time=09:00:00", path)
    if ixml:
        data = path.read_bytes()
        data += b"iXML" + struct.pack("<I", len(ixml)) + ixml + (b"\0" if len(ixml) % 2 else b"")
        path.write_bytes(data[:4] + struct.pack("<I", len(data) - 8) + data[8:])


@pytest.fixture(scope="module")
def card(tmp_path_factory):
    root = tmp_path_factory.mktemp("media") / "A001"
    clip = root / "PRIVATE/M4ROOT/CLIP"
    video(clip / "C0001.MP4", seconds=2, extra=("-timecode", "01:02:03:04", "-metadata", "creation_time=2026-10-12T23:10:00Z"))
    (clip / "C0001M01.XML").write_text("<NonRealTimeMeta/>")
    video(root / "PRIVATE/M4ROOT/SUB/C0001S03.MP4", size="160x120")  # proxy
    (root / "PRIVATE/M4ROOT/THMBNL").mkdir(parents=True)
    ffmpeg("-f", "lavfi", "-i", "testsrc=size=64x48", "-frames:v", 1, root / "PRIVATE/M4ROOT/THMBNL/C0001T01.JPG")
    video(root / "OTHER/prores.mov", rate="24000/1001", codec=("-c:v", "prores_ks", "-profile:v", "0"),
          extra=("-timecode", "10:00:00:00"))
    video(root / "OTHER/mpeg2.mxf", size="720x576", codec=("-c:v", "mpeg2video", "-f", "mxf"),
          extra=("-timecode", "12:34:56:00"))
    video(root / "OTHER/df.mp4", rate="30000/1001", extra=("-timecode", "01:00:00;02"))
    video(root / "OTHER/nometa.mp4", extra=("-map_metadata", "-1"))
    (root / "OTHER/corrupt.mp4").write_bytes(b"\0not a real video" * 100)
    bwf(root / "AUDIO/T001.WAV", IXML.replace(b"{rate}", b"25").replace(b"{flag}", b"NDF"))
    bwf(root / "AUDIO/T002.WAV", IXML.replace(b"{rate}", b"30000/1001").replace(b"{flag}", b"DF"))
    bwf(root / "AUDIO/T003.WAV")  # no iXML
    still = root / "DCIM/100MSDCF/DSC00001.JPG"
    still.parent.mkdir(parents=True)
    ffmpeg("-f", "lavfi", "-i", "testsrc=size=64x48", "-frames:v", 1, still)
    subprocess.run(["exiftool", "-q", "-overwrite_original", "-DateTimeOriginal=2026:10:12 23:59:58",
                    "-OffsetTimeOriginal=-06:00", "-Make=SONY", "-Model=ILCE-7SM3", str(still)], check=True)
    return root


@pytest.fixture(scope="module")
def clips(card):
    listing = list_source(card)
    by_path = {c.rel_path: c for c in extract_card(card, listing.files, {f.rel_path: "abc" for f in listing.files})}
    return by_path


def test_clip_selection(card):
    selected = {f.rel_path: kind for f, kind in select_clips(list_source(card).files)}
    assert "PRIVATE/M4ROOT/SUB/C0001S03.MP4" not in selected  # proxy
    assert "PRIVATE/M4ROOT/THMBNL/C0001T01.JPG" not in selected  # thumbnail
    assert "PRIVATE/M4ROOT/CLIP/C0001M01.XML" not in selected  # sidecar
    assert selected["PRIVATE/M4ROOT/CLIP/C0001.MP4"] == "video"
    assert selected["AUDIO/T001.WAV"] == "audio"
    assert selected["DCIM/100MSDCF/DSC00001.JPG"] == "still"


def test_h264_mp4(clips):
    c = clips["PRIVATE/M4ROOT/CLIP/C0001.MP4"]
    assert (c.filename, c.kind, c.xxh64) == ("C0001.MP4", "video", "abc")
    assert c.start_timecode == "01:02:03:04"
    assert c.codec.startswith("h264")
    assert (c.resolution, c.frame_rate) == ("320x240", "25")
    assert c.duration == pytest.approx(2.0, abs=0.05)
    assert c.size > 0
    assert c.sources["start_timecode"] == "ffprobe"


def test_container_time_kept_as_written(clips):
    c = clips["PRIVATE/M4ROOT/CLIP/C0001.MP4"]
    assert c.created == "2026-10-12T23:10:00"  # not shifted from "UTC"
    assert "not converted" in c.sources["created"]


def test_prores_23_976(clips):
    c = clips["OTHER/prores.mov"]
    assert (c.codec, c.frame_rate, c.start_timecode) == ("prores (Proxy)", "23.976", "10:00:00:00")


def test_mxf(clips):
    c = clips["OTHER/mpeg2.mxf"]
    assert (c.resolution, c.frame_rate, c.start_timecode) == ("720x576", "25", "12:34:56:00")
    assert c.created == ""  # MXF here has zero dates: blank, not guessed


def test_drop_frame(clips):
    c = clips["OTHER/df.mp4"]
    assert (c.frame_rate, c.start_timecode) == ("29.97", "01:00:00;02")


def test_no_metadata_leaves_fields_blank(clips):
    c = clips["OTHER/nometa.mp4"]
    assert c.created == "" and c.start_timecode == "" and c.camera_model == ""
    assert c.resolution == "320x240"  # technical fields still come from the stream


def test_unreadable_file(clips):
    c = clips["OTHER/corrupt.mp4"]
    assert (c.codec, c.resolution, c.frame_rate, c.start_timecode, c.created) == ("", "", "", "", "")
    assert c.duration is None
    assert "ffprobe could not read this file" in c.notes


def test_bwf_timecode_from_ixml(clips):
    c = clips["AUDIO/T001.WAV"]
    assert c.start_timecode == "01:00:00:00"
    assert (c.codec, c.sample_rate, c.channels) == ("pcm_s24le", 48000, 2)
    assert c.created == "2026-10-12T09:00:00"
    assert c.frame_rate == "25"
    assert "iXML" in c.sources["start_timecode"]


def test_bwf_drop_frame(clips):
    assert clips["AUDIO/T002.WAV"].start_timecode == "01:00:00;00"


def test_bwf_without_rate_left_blank(clips):
    c = clips["AUDIO/T003.WAV"]
    assert c.start_timecode == "" and c.frame_rate == ""
    assert any("no timecode rate" in n for n in c.notes)


def test_still(clips):
    c = clips["DCIM/100MSDCF/DSC00001.JPG"]
    assert c.created == "2026-10-12T23:59:58-06:00"
    assert c.camera_model == "SONY ILCE-7SM3"
    assert (c.resolution, c.codec) == ("64x48", "JPEG")
    assert c.duration is None and c.start_timecode == ""


@pytest.mark.parametrize("make, model, expected", [
    ("Canon", "Canon EOS C80", "Canon EOS C80"),
    ("SONY", "ILCE-7SM3", "SONY ILCE-7SM3"),
    ("", "ILCE-7SM3", "ILCE-7SM3"),
    ("Canon", "", "Canon"),
])
def test_camera_model(make, model, expected):
    assert camera_model({"Make": make, "Model": model}) == expected


def test_missing_tools_give_blank_fields(card):
    listing = list_source(card)
    clips = extract_card(card, listing.files, {}, exif={}, tools=ToolStatus(exiftool=None, ffprobe=None))
    assert clips and all(not c.codec and not c.start_timecode and not c.created for c in clips)


def test_clip_dates_for_shoot_date(card):
    clips = select_clips(list_source(card).files)
    exif = read_exif(card, [f.rel_path for f, _ in clips], find_tools().exiftool)
    times = clip_datetimes(exif, clips)
    assert datetime(2026, 10, 12, 23, 10) in times
    assert propose_shoot_date(times).proposed == date(2026, 10, 12)


def test_clips_across_midnight(tmp_path):
    video(tmp_path / "card/C0001.MP4", extra=("-metadata", "creation_time=2026-10-12T23:50:00Z"))
    video(tmp_path / "card/C0002.MP4", extra=("-metadata", "creation_time=2026-10-13T00:20:00Z"))
    clips = select_clips(list_source(tmp_path / "card").files)
    exif = read_exif(tmp_path / "card", [f.rel_path for f, _ in clips])
    proposal = propose_shoot_date(clip_datetimes(exif, clips))
    assert proposal.spans_midnight and proposal.proposed == date(2026, 10, 12)


@pytest.mark.parametrize("path, end", [
    ("PRIVATE/M4ROOT/CLIP/C0001.MP4", "01:02:05:04"),  # 2 s at 25 fps from 01:02:03:04
    ("OTHER/df.mp4", "01:00:01;02"),  # 30 frames of 29.97 DF from 01:00:00;02
    ("OTHER/prores.mov", "10:00:01:00"),  # 24 frames of 23.976
    ("AUDIO/T001.WAV", "01:00:01:00"),  # 1 s of BWF at 25 fps
])
def test_end_timecode(clips, path, end):
    assert clips[path].end_timecode == end
    assert clips[path].sources["end_timecode"] == "computed: start TC + duration"


def test_end_timecode_blank_without_start(clips):
    assert clips["OTHER/nometa.mp4"].end_timecode == ""
    assert clips["AUDIO/T003.WAV"].end_timecode == ""


# --- Sony XML sidecars (layout and values from a real FX6 card) ---------------

from media_ingest.metadata import read_sony_xml, sony_ltc

SONY_XML = """<?xml version="1.0" encoding="UTF-8"?>
<NonRealTimeMeta xmlns="urn:schemas-professionalDisc:nonRealTimeMeta:ver.2.20" lastUpdate="2026-10-05T22:16:46-08:00">
	<Duration value="48"/>
	<LtcChangeTable tcFps="24" halfStep="false">
		<LtcChange frameCount="0" value="{ltc}" status="increment"/>
	</LtcChangeTable>
	<CreationDate value="{created}"/>
	<Device manufacturer="Sony" modelName="ILME-FX6V" serialNo="0000000"/>
</NonRealTimeMeta>
"""


@pytest.mark.parametrize("value, tc, drop", [
    ("16493810", "10:38:49:16", False),  # real FX6 clip
    ("15271711", "11:17:27:15", False),
    ("00000000", "00:00:00:00", False),
    ("42000001", "01:00:00;02", True),  # drop-frame flag in the frames byte
])
def test_sony_ltc(value, tc, drop):
    assert sony_ltc(value) == (tc, drop)


@pytest.mark.parametrize("value", ["", "1649381", "zz493810", "1A493810"])
def test_sony_ltc_rejects(value):
    with pytest.raises(ValueError):
        sony_ltc(value)


@pytest.fixture
def fx6_card(tmp_path):
    """An XDROOT card whose MXF container time is UTC (next day) but the XML has local time."""
    clip = tmp_path / "Untitled/XDROOT/Clip/A002C001_2610059N.MXF"
    video(clip, codec=("-c:v", "mpeg2video", "-f", "mxf"), size="720x576",
          extra=("-timecode", "10:38:49:16", "-metadata", "creation_time=2026-10-06T05:30:00Z"))
    clip.with_name("A002C001_2610059NM01.XML").write_text(
        SONY_XML.format(ltc="16493810", created="2026-10-05T21:30:00-08:00"))
    return tmp_path / "Untitled"


def test_sony_xml_fields(fx6_card):
    got = read_sony_xml(fx6_card / "XDROOT/Clip/A002C001_2610059N.MXF")
    assert got["created"] == "2026-10-05T21:30:00-08:00"
    assert got["camera_model"] == "Sony ILME-FX6V" and got["camera_serial"] == "0000000"
    assert got["start_timecode"] == "10:38:49:16"


def test_sony_xml_wins_over_utc_container_time(fx6_card):
    listing = list_source(fx6_card)
    (c,) = extract_card(fx6_card, listing.files, {})
    assert c.created == "2026-10-05T21:30:00-08:00"
    assert c.sources["created"].startswith("Sony XML CreationDate")
    assert c.camera_model == "Sony ILME-FX6V (S/N 0000000)"
    assert c.start_timecode == "10:38:49:16" and c.sources["start_timecode"] == "ffprobe" and not c.notes


def test_shoot_date_uses_sony_local_time(fx6_card):
    clips = select_clips(list_source(fx6_card).files)
    exif = read_exif(fx6_card, [f.rel_path for f, _ in clips])
    assert propose_shoot_date(clip_datetimes(exif, clips)).proposed == date(2026, 10, 6)  # UTC: wrong day
    assert propose_shoot_date(clip_datetimes(exif, clips, root=fx6_card)).proposed == date(2026, 10, 5)


def test_sony_xml_timecode_disagreement_is_noted(fx6_card):
    xml = fx6_card / "XDROOT/Clip/A002C001_2610059NM01.XML"
    xml.write_text(SONY_XML.format(ltc="00000001", created="2026-10-05T21:30:00-08:00"))
    (c,) = extract_card(fx6_card, list_source(fx6_card).files, {})
    assert c.start_timecode == "10:38:49:16"
    assert any("differs from its Sony XML (01:00:00:00)" in n for n in c.notes)


def test_broken_or_foreign_sidecar_ignored(fx6_card):
    xml = fx6_card / "XDROOT/Clip/A002C001_2610059NM01.XML"
    xml.write_text("<not closed")
    assert read_sony_xml(fx6_card / "XDROOT/Clip/A002C001_2610059N.MXF") == {}
    xml.write_text("<SomethingElse><CreationDate value='2020-01-01T00:00:00'/></SomethingElse>")
    assert read_sony_xml(fx6_card / "XDROOT/Clip/A002C001_2610059N.MXF") == {}
